inline bool familiar(const float features[16]) {
  float nearest=INFINITY;
  for (const auto& center:support_centers) {
    float distance=0; for(unsigned i=0;i<16;++i) {float delta=(features[i]-mean[i])/scale[i]-center[i];distance+=delta*delta;}
    if(distance<nearest)nearest=distance;
  }
  return nearest<=30.785746f;
}
